import hashlib, json, os, subprocess, sys
ee = sys.argv[1]
SCHEMA = "ee.ambient_context.v1"
SURFACE = "pre_edit_recall"
DEFAULT_BUDGET = 400
QUIET_BUDGET = 200
VERBOSE_BUDGET = 800
DEFAULT_MAX_PATHS = 8
QUIET_MAX_PATHS = 4
VERBOSE_MAX_PATHS = 12
try:
    data = json.load(sys.stdin)
except Exception:
    sys.exit(0)
if not isinstance(data, dict):
    sys.exit(0)
def ambient_enabled():
    value = os.environ.get("EE_AMBIENT_CONTEXT", "true").strip().lower()
    return value not in ("0", "false", "off", "no", "disable", "disabled")
def ambient_verbosity():
    value = os.environ.get("EE_AMBIENT_CONTEXT_VERBOSITY", "standard").strip().lower()
    if value in ("quiet", "standard", "verbose"):
        return value
    return "standard"
if not ambient_enabled():
    sys.exit(0)
VERBOSITY = ambient_verbosity()
BUDGET = {"quiet": QUIET_BUDGET, "standard": DEFAULT_BUDGET, "verbose": VERBOSE_BUDGET}[VERBOSITY]
MAX_PATHS = {"quiet": QUIET_MAX_PATHS, "standard": DEFAULT_MAX_PATHS, "verbose": VERBOSE_MAX_PATHS}[VERBOSITY]
def state_path():
    try:
        root = _ee_state_root()
        os.makedirs(root, exist_ok=True)
    except Exception:
        return None
    return os.path.join(root, "ambient_context_seen.json")
def already_seen(text):
    path = state_path()
    if not path:
        return False
    session = str(data.get("session_id") or data.get("sessionId") or "default")
    key = SURFACE + ":" + session + ":" + hashlib.blake2s(text.encode("utf-8"), digest_size=16).hexdigest()
    try:
        with open(path, "r", encoding="utf-8") as f:
            seen = json.load(f)
    except Exception:
        seen = {}
    if not isinstance(seen, dict):
        seen = {}
    if seen.get(key):
        return True
    seen[key] = True
    try:
        with open(path, "w", encoding="utf-8") as f:
            json.dump(seen, f, sort_keys=True, separators=(",", ":"))
    except Exception:
        pass
    return False
def emit(text, codes):
    if already_seen(text):
        _ee_record_invocation("duplicate", degraded_codes=codes)
        return
    header = f"<!-- ee ambient_context schema={SCHEMA} surface={SURFACE} budgetTokens={BUDGET} maxPaths={MAX_PATHS} verbosity={VERBOSITY} provenance=ee:{SCHEMA} -->"
    payload = {"hookSpecificOutput": {"hookEventName": data.get("hook_event_name") or "PreToolUse", "additionalContext": header + "\n" + text}}
    print(json.dumps(payload, separators=(",", ":")))
    _ee_record_invocation("emitted", len(payload["hookSpecificOutput"]["additionalContext"].encode("utf-8")), codes)
tool_input = data.get("tool_input") or {}
if not isinstance(tool_input, dict):
    sys.exit(0)
paths = []
for key in ("file_path", "path", "notebook_path"):
    value = tool_input.get(key)
    if isinstance(value, str) and value:
        paths.append(value)
edits = tool_input.get("edits")
if edits is None:
    edits = []
if not isinstance(edits, list):
    sys.exit(0)
for edit in edits:
    if isinstance(edit, dict):
        value = edit.get("file_path") or edit.get("path")
        if isinstance(value, str) and value:
            paths.append(value)
seen = []
workspace = os.path.abspath(data.get("cwd") or os.getcwd())
for path in paths:
    # Harnesses commonly send absolute file paths; the anchor index stores
    # workspace-relative paths. Ignore edits outside this workspace.
    path = os.path.relpath(os.path.abspath(os.path.join(workspace, path)), workspace)
    if path == os.pardir or path.startswith(os.pardir + os.sep):
        continue
    if path not in seen:
        seen.append(path)
if not seen:
    sys.exit(0)
cmd = [ee, "recall", "--use-daemon"]
for path in seen[:MAX_PATHS]:
    cmd.extend(["--path", path])
cmd.extend(["--budget-tokens", str(BUDGET), "--format", "hook", "--fields", "command,ambientContext"])
try:
    result = subprocess.run(cmd, cwd=data.get("cwd") or None, text=True, capture_output=True, timeout=9)
except subprocess.TimeoutExpired:
    _ee_record_invocation("timeout")
    sys.exit(0)
except Exception:
    _ee_record_invocation("command_error")
    sys.exit(0)
if result.returncode != 0:
    _ee_record_invocation("command_error")
    sys.exit(0)
try:
    response = json.loads(result.stdout)
    if response.get("success") is not True:
        raise ValueError("unsuccessful response")
    text = response["data"]["ambientContext"]["text"].strip()
    codes = sorted({entry["code"] for entry in response.get("degraded", []) if isinstance(entry.get("code"), str)})
except Exception:
    _ee_record_invocation("invalid_response")
    sys.exit(0)
if not text:
    _ee_record_invocation("empty", degraded_codes=codes)
    sys.exit(0)
emit(text, codes)

