def _ee_lock_context_state(lock, timeout_seconds):
    # Keep one stable lock inode: replacing or unlinking it splits the writers.
    deadline = time.monotonic() + timeout_seconds
    while True:
        try:
            if os.name == "nt":
                import msvcrt
                lock.seek(0)
                msvcrt.locking(lock.fileno(), msvcrt.LK_NBLCK, 1)
            else:
                import fcntl
                fcntl.flock(lock.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
            return True
        except OSError as error:
            if error.errno not in (errno.EACCES, errno.EAGAIN):
                return False
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                return False
            time.sleep(min(0.005, remaining))
def _ee_write_json_atomic(path, value, lock=None):
    pending = None
    try:
        with tempfile.NamedTemporaryFile(mode="w", encoding="utf-8", dir=os.path.dirname(path), prefix=".ee-hook-", suffix=".tmp", delete=False) as f:
            pending = f.name
            json.dump(value, f, sort_keys=True, separators=(",", ":"))
        if lock is not None and not os.path.samestat(os.fstat(lock.fileno()), os.lstat(path + ".lock")):
            raise OSError("ambient context lock changed before publication")
        os.replace(pending, path)
        pending = None
    finally:
        if pending is not None:
            try:
                os.unlink(pending)
            except OSError:
                pass
